"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "payments",
    "name": "payments-worker",
    "uid": "uid-deployment-payments-worker"
  },
  "params": {
    "container": "app",
    "liveness": {
      "timeoutSeconds": 10
    }
  },
  "expected_effect": "Increase the liveness probe timeout to 10 seconds, allowing the new app version sufficient time to start and respond to health checks before being terminated.",
  "rationale": "The liveness probe timeout of 2 seconds is too short for the new app version, which is taking longer to start. Increasing the timeout to 10 seconds aligns with the observed startup time of 46 seconds and prevents premature termination during startup.",
